 'use strict';
const $=s=>document.querySelector(s);
const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[{id:'deep',text:'Give deep work a full 90 minutes.',active:true},{id:'meetings',text:'Keep team meetings where they are.',active:true},{id:'workout',text:'A workout can move. A proper break stays.',active:true}];
let memory,activity;
try{memory=JSON.parse(localStorage.getItem('jarvis.memory'))||structuredClone(defaults);activity=JSON.parse(localStorage.getItem('jarvis.activity'))||[]}catch{memory=structuredClone(defaults);activity=[]}
let currentPlan=null,recognition=null,busy=false,voiceOn=true,sequence=0,toastTimer,panelName='',panelOpener=null;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3300)}
function phase(name,label){document.body.dataset.phase=name;$('#voice-state').textContent=label;$('#voice-button').setAttribute('aria-label',name==='listening'?'Finish speaking':'Speak to Jarvis');$('#speak-label').innerHTML=name==='listening'?'Finish speaking <span>✓</span>':'Speak to Jarvis <span>↗</span>';$('#voice-button').disabled=busy;$('#speak-label').disabled=busy}
function caption(text){$('#response-caption').textContent=text;$('#response-caption').hidden=!text}
function greeting(title,detail){$('#greeting').textContent=title;$('#greeting-detail').textContent=detail}
function rest(){phase(currentPlan&&!currentPlan.applied?'review':'idle',currentPlan&&!currentPlan.applied?'Awaiting your approval, sir.':'At your service, sir.')}
function interrupt(){if(window.speechSynthesis)window.speechSynthesis.cancel();if(document.body.dataset.phase==='speaking')rest()}
function reply(text){caption(text);rest();if(!voiceOn||!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-GB';utterance.rate=.96;utterance.pitch=.88;utterance.onstart=()=>{if(!recognition&&!busy)phase('speaking','Speaking')};utterance.onend=()=>{if(!recognition&&!busy)rest()};utterance.onerror=()=>{if(!recognition&&!busy)rest()};window.speechSynthesis.speak(utterance)}
$('#sound-button').onclick=()=>{voiceOn=!voiceOn;$('#sound-button').classList.toggle('muted',!voiceOn);$('#sound-button').setAttribute('aria-label',voiceOn?'Mute assistant voice':'Unmute assistant voice');if(!voiceOn)interrupt();toast(voiceOn?'Voice enabled.':'Voice muted. Captions remain visible.')};
function persist(){try{localStorage.setItem('jarvis.memory',JSON.stringify(memory));localStorage.setItem('jarvis.activity',JSON.stringify(activity))}catch{}renderScheduled()}
function openPanel(name){panelOpener=document.activeElement;panelName=name;$('#detail-panel').hidden=false;$('#panel-backdrop').hidden=false;$('#panel-title').textContent={memory:'What I remember.',activity:'Action record.',context:'Context in use.'}[name];$('#panel-kicker').textContent={memory:'PERSONAL PREFERENCES',activity:'COMPLETED AND REVERSED',context:'VISIBLE SOURCES'}[name];renderPanel();$('#close-panel').focus()}
function closePanel(){$('#detail-panel').hidden=true;$('#panel-backdrop').hidden=true;panelName='';panelOpener?.focus()}
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('#close-panel').onclick=closePanel;$('#panel-backdrop').onclick=closePanel;
function closeDemo(){$('#demo-menu').hidden=true;$('#demo-button').setAttribute('aria-expanded','false')}
$('#demo-button').onclick=()=>{const open=$('#demo-menu').hidden;$('#demo-menu').hidden=!open;$('#demo-button').setAttribute('aria-expanded',String(open))};$('#close-demo').onclick=closeDemo;
const commands={focus:'Find ninety minutes for my portfolio this week. Move my workout only if needed.',afternoon:'Arrange my afternoon, Jarvis. I need groceries and time for the design review.',tomorrow:'Keep tomorrow morning free for learning, and leave a proper break.'};
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{closeDemo();handleCommand(commands[b.dataset.demo]);});
async function handleCommand(prompt){prompt=prompt.trim();if(!prompt||busy)return;interrupt();closePanelIfOpen();closeDemo();$('#heard-caption').hidden=false;$('#heard-caption').textContent='HEARD · '+prompt;const low=prompt.toLowerCase();
if(/^(hello|hi|hey|good morning|good evening|jarvis)[.!\s]*$/i.test(prompt)){greeting('At your service, sir.','What are we working on today?');reply('At your service, Captain.');return}
if(/my (day|schedule)|what.*(today|next)/.test(low)){reply('Design review at nine. Check-in at two. Workout at five thirty, sir.');return}
if(/\b(undo|reverse|restore)\b/.test(low)){const latest=activity.find(a=>!a.undone);if(latest)undo(latest.id);else reply('Nothing to undo, sir.');return}
if(/\b(cancel|dismiss|never mind)\b/.test(low)){currentPlan=null;renderReview();greeting('Standing by, Captain.','At your service.');reply('Cancelled, sir. Nothing changed.');return}
if(/\b(approve|proceed|go ahead|confirm|do it)\b/.test(low)){if(currentPlan&&!currentPlan.applied)approvePlan();else reply('No changes awaiting approval, sir.');return}
if(currentPlan&&!currentPlan.applied&&/\b(earlier|later|morning|afternoon|original)\b/.test(low)&&!(/arrange|grocer|learning|learn/.test(low))){currentPlan.timeChoice=/original/.test(low)?'original':/later|afternoon/.test(low)?'afternoon':'morning';currentPlan.actions[0].detail=currentPlan.timeChoice==='original'?currentPlan.originalDetails[0]:adjustedWindow(currentPlan,currentPlan.timeChoice);renderReview();reply('Adjusted, sir. The revised time is on your schedule.');return}
if(/delete|email|buy|pay|password|flight/.test(low)){reply('That service is not connected, sir. Calendar and tasks are available in this demonstration.');return}
busy=true;phase('thinking','Checking your schedule');greeting('On it, Captain.','Checking the available windows.');caption('');const ticket=++sequence;await new Promise(r=>setTimeout(r,850));if(ticket!==sequence)return;
const kind=/afternoon|grocer/.test(low)?'afternoon':/learning|learn|tomorrow morning/.test(low)?'tomorrow':'focus';currentPlan=makePlan(kind,prompt);currentPlan.originalDetails=currentPlan.actions.map(a=>a.detail);currentPlan.timeChoice='original';busy=false;renderReview();greeting('Your plan is ready, Captain.','Nothing changes without your approval.');reply(kind==='focus'?`A ${currentPlan.actions[0].time.replace(' min','-minute')} block tomorrow at 10:30. Your workout stays put. Shall I proceed?`:kind==='afternoon'?'Review at three. Groceries at five. Your check-in stays put. Shall I proceed?':'Learning at ten. A break at eleven. Shall I proceed?');revealReviewOnMobile();}
function closePanelIfOpen(){if(panelName)closePanel()}
function revealReviewOnMobile(){if(window.matchMedia('(max-width:760px)').matches)$('#action-review').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'})}
function renderReview(){const el=$('#action-review');el.hidden=!currentPlan;if(!currentPlan){el.innerHTML='';return}const p=currentPlan;el.className='action-review';if(p.applied){el.innerHTML=`<div class="review-label"><span>✓ ACTION RECEIPT</span><button data-source>Context ↗</button></div><h3>Done, Captain.</h3>${p.actions.map(a=>`<div class="receipt-item"><span>${a.selected?'✓':'−'}</span><div>${escapeHtml(a.title)}<small>${a.selected?escapeHtml(a.detail):'Skipped. No change.'}</small></div></div>`).join('')}<p class="review-note">Meetings protected. No new memory saved.</p><div class="receipt-buttons"><button id="undo-plan" class="secondary-button">Undo</button><button id="dismiss-plan" class="primary-button">Dismiss</button></div>`;$('#undo-plan').onclick=()=>undo(p.id);$('#dismiss-plan').onclick=()=>{currentPlan=null;renderReview();greeting('At your service, sir.','What is next, Captain?');caption('');rest()};}else{const n=p.actions.filter(a=>a.selected).length;el.innerHTML=`<div class="review-label"><span>AWAITING APPROVAL</span><button data-source>Context ↗</button></div><h3>${escapeHtml(p.title)}</h3>${p.actions.map(a=>`<label class="action-choice"><input type="checkbox" data-action="${a.id}" ${a.selected?'checked':''}><span>${escapeHtml(a.title)}<small>${escapeHtml(a.detail)}</small><em>${escapeHtml(a.reason)}</em></span></label>`).join('')}<div class="review-adjust"><label for="time-select">Time window</label><select id="time-select"><option value="original" ${p.timeChoice==='original'?'selected':''}>Original</option><option value="morning" ${p.timeChoice==='morning'?'selected':''}>Earlier</option><option value="afternoon" ${p.timeChoice==='afternoon'?'selected':''}>Later</option></select></div><button id="approve-plan" class="primary-button approve-button" ${n?'':'disabled'}>Approve ${n} ${n===1?'change':'changes'}</button><p class="review-note">Or say “proceed”, “later” or “cancel”.</p>`;document.querySelectorAll('[data-action]').forEach(c=>c.onchange=()=>{p.actions.find(a=>a.id===c.dataset.action).selected=c.checked;renderReview()});$('#time-select').onchange=e=>{p.timeChoice=e.target.value;p.actions[0].detail=p.timeChoice==='original'?p.originalDetails[0]:adjustedWindow(p,p.timeChoice);renderReview();reply('Time adjusted, sir. Awaiting your approval.')};$('#approve-plan').onclick=approvePlan;}el.querySelector('[data-source]').onclick=()=>openPanel('context')}
function approvePlan(){if(!currentPlan||currentPlan.applied)return;const n=currentPlan.actions.filter(a=>a.selected).length;if(!n){reply('Select at least one change, sir.');return}if(activity.some(a=>a.id===currentPlan.id))currentPlan.id=Date.now();currentPlan.applied=true;currentPlan.timestamp=new Date().toISOString();activity.unshift(structuredClone(currentPlan));persist();renderReview();greeting('Consider it arranged, Captain.','Your schedule has been updated.');reply(`${n===1?'One change':n+' changes'} completed, sir. Your meetings remain protected.`)}
function undo(id){const p=activity.find(a=>a.id===id);if(!p||p.undone)return;p.undone=true;persist();if(currentPlan?.id===id){currentPlan.applied=false;renderReview()}if(panelName==='activity')renderPanel();greeting('Restored, Captain.','Your original schedule is intact.');reply('Reversed, sir. Your original schedule is restored.')}
function renderScheduled(){const plans=activity.filter(a=>!a.undone);$('#scheduled-changes').innerHTML=plans.length?`<div class="section-caption">ARRANGED BY JARVIS <span>${plans.length}</span></div>${plans.flatMap(p=>p.actions.filter(a=>a.selected)).map(a=>`<div class="scheduled-item">✓ ${escapeHtml(a.title)}<small>${escapeHtml(a.detail)}</small></div>`).join('')}`:'';$('#schedule-insight').textContent=plans.length?'Your approved changes are in place.':'4 hours clear before your next meeting.'}
function renderPanel(){const content=$('#panel-content');if(panelName==='context'){content.innerHTML=`<p class="panel-intro">The sources behind this recommendation.</p><div class="context-source"><h3>Calendar</h3><p>Tuesday: three fixed and flexible events.<br>Wednesday: an open morning.</p><small>Example calendar</small></div><div class="context-source"><h3>Tasks</h3><p>Portfolio case study · groceries</p><small>Example tasks</small></div><div class="context-source"><h3>Memory</h3><p>${memory.filter(m=>m.active).length} active preferences</p><button id="review-memory">Review preferences ↗</button></div><p class="muted-copy">Changes affect this browser's sample workspace. No external services are connected.</p>`;$('#review-memory').onclick=()=>openPanel('memory');return}if(panelName==='activity'){content.innerHTML=activity.length?activity.map(a=>`<article class="activity-entry"><span class="eyebrow">${a.undone?'REVERSED':'COMPLETED'}</span><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.prompt)}</p><ul>${a.actions.filter(x=>x.selected).map(x=>`<li>${escapeHtml(x.title)} · ${escapeHtml(x.detail)}</li>`).join('')}</ul>${a.undone?'':`<button class="secondary-button" data-undo="${a.id}">Undo changes</button>`}</article>`).join(''):'<div class="empty-state">No actions yet, sir.</div>';document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>undo(Number(b.dataset.undo)));return}content.innerHTML=`<p class="panel-intro">Preferences stay visible and under your control.</p><div id="memory-list">${memory.map(m=>`<article class="memory-card ${m.active?'':'inactive'}"><input type="checkbox" aria-label="Use preference: ${escapeHtml(m.text)}" data-memory="${m.id}" ${m.active?'checked':''}><div><h3>${escapeHtml(m.text)}</h3><p>${m.active?'Enabled':'Paused'}</p></div><button data-edit="${m.id}">Edit</button><button data-forget="${m.id}">Forget</button></article>`).join('')}</div><form id="memory-form" class="memory-form"><label for="new-memory">Add a preference</label><div><input id="new-memory" placeholder="Your preference" maxlength="160"><button class="primary-button">Save</button></div></form><p class="muted-copy">Stored locally. Demo planning reads the preset preference flags; custom text is saved for the future conversational build.</p>`;
document.querySelectorAll('[data-memory]').forEach(c=>c.onchange=()=>{memory.find(m=>m.id===c.dataset.memory).active=c.checked;persist();renderPanel()});document.querySelectorAll('[data-forget]').forEach(b=>b.onclick=()=>{memory=memory.filter(m=>m.id!==b.dataset.forget);persist();renderPanel()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const m=memory.find(m=>m.id===b.dataset.edit),h=b.closest('.memory-card').querySelector('h3'),input=document.createElement('input');input.className='memory-edit';input.value=m.text;input.maxLength=160;input.setAttribute('aria-label','Edit preference');h.replaceWith(input);input.focus();input.select();let done=false;const save=()=>{if(done)return;done=true;m.text=input.value.trim()||m.text;persist();renderPanel()};input.onblur=save;input.onkeydown=e=>{if(e.key==='Enter')save();if(e.key==='Escape'){done=true;renderPanel()}}});$('#memory-form').onsubmit=e=>{e.preventDefault();const text=$('#new-memory').value.trim();if(!text)return;memory.push({id:'m'+Date.now(),text,active:true});persist();renderPanel()};}
function startVoice(){if(busy)return;if(recognition){recognition.stop();return}interrupt();closeDemo();const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){phase('idle','Voice unavailable in this browser');caption('Microphone input needs a supported browser, sir. Preview a sample command below.');return}let transcript='',failed=false,cancelled=false;recognition=new SpeechRecognition();recognition.lang='en-IN';recognition.interimResults=true;recognition.continuous=false;recognition.onresult=e=>{transcript=Array.from(e.results,r=>r[0].transcript).join(' ');$('#heard-caption').textContent='HEARING · '+transcript;$('#heard-caption').hidden=false};recognition.onerror=e=>{failed=true;caption(e.error==='not-allowed'?'Microphone access is unavailable, sir. You can preview a command below.':'I did not catch that, sir. Please try again.');rest()};recognition.onend=()=>{recognition=null;if(!failed&&!cancelled&&transcript.trim())handleCommand(transcript);else{greeting(currentPlan?'Your plan is ready, Captain.':'At your service, sir.',currentPlan?'Awaiting your approval.':'What are we working on today?');if(!failed&&!cancelled)caption('I did not catch a request, sir. Please try again.');rest()}};recognition.cancel=()=>{cancelled=true;recognition.abort()};try{recognition.start();phase('listening','Listening, Captain.');greeting('Listening, Captain.','I am at your service.');caption('');$('#heard-caption').hidden=true}catch{recognition=null;rest();caption('Microphone unavailable, sir. Preview a sample command below.')}}
$('#voice-button').onclick=startVoice;$('#speak-label').onclick=startVoice;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){recognition?.cancel();interrupt();closePanelIfOpen();closeDemo();rest()}if(e.code==='Space'&&!e.repeat&&!/INPUT|SELECT|BUTTON|TEXTAREA/.test(document.activeElement.tagName)&&!panelName){e.preventDefault();startVoice()}if(e.key==='Tab'&&panelName){const nodes=[...$('#detail-panel').querySelectorAll('button,input,select,a')].filter(n=>!n.disabled),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#reset-demo').onclick=()=>{sequence++;busy=false;recognition?.cancel();interrupt();memory=structuredClone(defaults);activity=[];currentPlan=null;persist();renderReview();closePanelIfOpen();closeDemo();greeting('Welcome back, Captain.','What are we working on today?');caption('');$('#heard-caption').hidden=true;rest();toast('Demo reset.')};
persist();const scene=new URLSearchParams(location.search).get('scene');if(scene&&commands[scene]){currentPlan=makePlan(scene,commands[scene]);currentPlan.originalDetails=currentPlan.actions.map(a=>a.detail);currentPlan.timeChoice='original';renderReview();greeting('Your plan is ready, Captain.','Nothing changes without your approval.');caption(scene==='focus'?'Ninety minutes tomorrow at 10:30. Shall I proceed?':scene==='afternoon'?'Review at three. Groceries at five. Shall I proceed?':'Learning at ten. A break at eleven. Shall I proceed?');$('#heard-caption').textContent='HEARD · '+commands[scene];$('#heard-caption').hidden=false;rest()}

function makePlan(kind,prompt){const protect=memory.some(m=>m.id==='meetings'&&m.active);const direct=prompt.match(/\b(\d{1,3})[-\s]*(?:min(?:ute)?s?)\b/i);const requested=/ninety/i.test(prompt)?90:/sixty/i.test(prompt)?60:direct?Math.max(15,Math.min(180,Number(direct[1]))):null;const duration=requested??(memory.some(m=>m.id==='deep'&&m.active)?90:60);const endMinutes=10*60+30+duration;const end=`${String(Math.floor(endMinutes/60)).padStart(2,'0')}:${String(endMinutes%60).padStart(2,'0')}`;const fixed=protect?'Team meetings stay exactly where they are.':'Existing commitments remain unchanged in this plan.';if(kind==='afternoon')return {id:Date.now(),kind,title:'Afternoon, arranged.',summary:'I can group the groceries with your trip out, then protect a quiet hour for the design review. Your check-in stays in place.',prompt,note:fixed,actions:[{id:'review',title:'Protect time for the design review',detail:'Today · 15:00-16:00 · Personal calendar',time:'60 min',reason:'After your project check-in; before your workout.',selected:true},{id:'groceries',title:'Move groceries to your next trip out',detail:'Today · 17:00 · Task reminder',time:'30 min',reason:'An errand on the way, rather than a separate trip.',selected:true}]};if(kind==='tomorrow')return {id:Date.now(),kind,title:'Tomorrow morning, reserved.',summary:'Let’s put learning in your first quiet hour and keep a proper break afterward. Two small changes, with room left unplanned.',prompt,note:'No existing events are moved. Your break stays protected.',actions:[{id:'learn',title:'Make room to learn something new',detail:'Wednesday · 10:00-11:00 · Personal calendar',time:'60 min',reason:'A clear morning window in your sample calendar.',selected:true},{id:'break',title:'Keep an unhurried break',detail:'Wednesday · 11:00-11:30 · Personal calendar',time:'30 min',reason:'Based on your preference to protect a proper break.',selected:true}]};return {id:Date.now(),kind:'focus',title:`${duration===90?'Ninety':duration===60?'Sixty':duration} minutes for your portfolio.`,summary:`There’s a clear ${duration}-minute window tomorrow at 10:30. I can protect it for your portfolio and move the task into that block. Your workout and team meetings can stay where they are.`,prompt,note:fixed+' Your workout is untouched.',actions:[{id:'focus',title:'Reserve a portfolio focus block',detail:`Wednesday · 10:30-${end} · Personal calendar`,time:duration+' min',reason:requested?'A clear window, based on the duration you asked for.':duration===90?'Matched to your deep-work preference.':'A clear one-hour window in your sample calendar.',selected:true},{id:'task',title:'Link the case study task to this block',detail:'Portfolio case study · Task list',time:'Task',reason:'One place to return to the work when the session starts.',selected:true}]}}

function adjustedWindow(p,choice){const minutes=parseInt(p.actions[0].time)||60;const hour=choice==='afternoon'?15:p.kind==='afternoon'?10:9;const endHour=hour+Math.floor(minutes/60);const endMinute=minutes%60;const day=p.kind==='afternoon'?'Today':'Wednesday';return `${day} · ${String(hour).padStart(2,'0')}:00-${String(endHour).padStart(2,'0')}:${String(endMinute).padStart(2,'0')} · Personal calendar`}
